#[test]
fn size_t_accessors_match() {
    setup();
    for name in SIZE_T_FNS {
        let (c, r) = pair::<unsafe extern "C" fn() -> usize>(name);
        let (a, b) = unsafe { (c(), r()) };
        assert_eq!(a, b, "{name}(): C returned {a}, Rust returned {b}");
    }
    assert_eq!(SIZE_T_FNS.len(), 303);
}

